// Read-only inspection ahead of the better-auth migration. Prints collection
// names and document counts for the databases on MONGODB_URI. Never prints the
// URI itself — it carries credentials.
import { MongoClient } from "mongodb";

const uri = process.env.MONGODB_URI;
if (!uri) {
  throw new Error("MONGODB_URI is required");
}

const client = new MongoClient(uri, { maxPoolSize: 2 });
await client.connect();
try {
  const { databases } = await client.db().admin().listDatabases();
  for (const { name } of databases) {
    if (name === "admin" || name === "local" || name === "config") {
      continue;
    }
    const db = client.db(name);
    const collections = await db.listCollections().toArray();
    process.stdout.write(`\n=== ${name} ===\n`);
    if (collections.length === 0) {
      process.stdout.write("  (no collections)\n");
      continue;
    }
    for (const { name: collectionName } of collections) {
      const count = await db.collection(collectionName).countDocuments();
      process.stdout.write(`  ${collectionName}: ${count}\n`);
    }
  }
} finally {
  await client.close();
}

