1	// Copies better-auth's collections off the MongoDB driver's implicit "test"
2	// database default and onto the explicit database the rest of the app
3	// already uses. See packages/auth/instance.ts and docs/knowledge-eval-
4	// findings.md's F3 for the history and the decision this executes.
5	//
6	//   MONGODB_URI=... bun scripts/migrate-to-app-db.ts             # dry run
7	//   MONGODB_URI=... bun scripts/migrate-to-app-db.ts --apply     # write
8	//
9	// Source/target database names default to "test" and (MONGODB_DB ?? "app"),
10	// matching packages/auth/instance.ts and packages/database/index.ts. Both
11	// live on the one cluster MONGODB_URI points at — this never opens a second
12	// connection. Override for testing with --source=<name>/--target=<name> or
13	// MONGODB_MIGRATE_SOURCE_DB/MONGODB_MIGRATE_TARGET_DB.
14	//
15	// DESIGN, all load-bearing:
16	//
17	// - COPY, NEVER MOVE. Nothing is ever deleted from the source database.
18	//   Dropping "test" is a separate, later, manual decision the maintainer
19	//   makes after confirming login works against the target.
20	// - DRY RUN BY DEFAULT. Only --apply writes anything; an accidental
21	//   invocation reports a plan and changes nothing.
22	// - IDEMPOTENT BY TOLERATING DUPLICATES, NOT BY PRE-READING. Documents are
23	//   inserted with insertMany({ ordered: false }), and duplicate-key (11000)
24	//   errors are swallowed rather than treated as failures: a document that
25	//   already exists at the same _id in the target is, by construction, a
26	//   copy of that same source document from an earlier run of this script —
27	//   nothing else writes to the target's better-auth collections before this
28	//   migration is applied and the config flip ships. Pre-reading every _id
29	//   first would cost an extra round trip per document for no benefit here.
30	// - COLLECTIONS ARE DISCOVERED, NOT HARDCODED. better-auth creates
31	//   collections lazily depending on which plugins are enabled (this repo
32	//   currently enables only `organization`, but `verification`, `jwks`,
33	//   `twoFactor`, `passkey`, etc. are plausible future additions) — a fixed
34	//   list would silently stop covering new ones.
35	// - INDEXES ARE COPIED TOO. better-auth relies on unique indexes (e.g.
36	//   user.email, session.token) to enforce constraints the app depends on;
37	//   copying documents without them leaves the target functionally broken
38	//   even once every document is in place. The implicit `_id_` index is
39	//   skipped — every collection already has it.
40	// - VERIFIED. After --apply, every collection is recounted on both sides
41	//   and the script exits non-zero on any mismatch.
42	//
43	// ORDERING (see packages/auth/instance.ts): this script must run, and its
44	// verify pass must come back clean, BEFORE any deploy that changes
45	// instance.ts's `client.db()` call to read `MONGODB_DB ?? "app"`. Deploying
46	// the config change first points the running app at an empty database and
47	// signs every user out.
48	//
49	// Never prints the connection string or any credential — only database
50	// names and counts.
51	
52	import {
53	  type Collection,
54	  type Db,
55	  type Document,
56	  type IndexDescription,
57	  type IndexDescriptionInfo,
58	  MongoBulkWriteError,
59	  MongoClient,
60	} from "mongodb";
61	
62	const DUPLICATE_KEY_ERROR_CODE = 11_000;
63	const INSERT_BATCH_SIZE = 500;
64	const DEFAULT_SOURCE_DB = "test";
65	const ID_INDEX_NAME = "_id_";
66	const SOURCE_FLAG_PREFIX = "--source=";
67	const TARGET_FLAG_PREFIX = "--target=";
68	
69	interface Args {
70	  readonly apply: boolean;
71	  readonly source: string;
72	  readonly target: string;
73	}
74	
75	export const parseArgs = (argv: readonly string[]): Args => {
76	  let apply = false;
77	  let source = process.env.MONGODB_MIGRATE_SOURCE_DB ?? DEFAULT_SOURCE_DB;
78	  let target =
79	    process.env.MONGODB_MIGRATE_TARGET_DB ?? process.env.MONGODB_DB ?? "app";
80	
81	  for (const arg of argv) {
82	    if (arg === "--apply") {
83	      apply = true;
84	    } else if (arg.startsWith(SOURCE_FLAG_PREFIX)) {
85	      source = arg.slice(SOURCE_FLAG_PREFIX.length);
86	    } else if (arg.startsWith(TARGET_FLAG_PREFIX)) {
87	      target = arg.slice(TARGET_FLAG_PREFIX.length);
88	    } else {
89	      console.error(`Unrecognized argument: ${arg}`);
90	      process.exit(1);
91	    }
92	  }
93	
94	  return { apply, source, target };
95	};
96	
97	/** Strips server-reported metadata (`v`, `ns`) that `createIndexes` rejects. */
98	const toIndexSpec = (info: IndexDescriptionInfo): IndexDescription => {
99	  const {
100	    key,
101	    name,
102	    v: _v,
103	    ns: _ns,
104	    ...options
105	  } = info as IndexDescriptionInfo & {
106	    ns?: string;
107	  };
108	  return { key, name, ...options } as IndexDescription;
109	};
110	
111	interface CollectionPlan {
112	  readonly indexSpecs: IndexDescription[];
113	  readonly name: string;
114	  readonly sourceCount: number;
115	  readonly targetCountBefore: number;
116	}
117	
118	const listCollectionNames = async (db: Db): Promise<string[]> => {
119	  const collections = await db
120	    .listCollections({}, { nameOnly: false })
121	    .toArray();
122	  return collections
123	    .filter((info) => info.type !== "view" && !info.name.startsWith("system."))
124	    .map((info) => info.name)
125	    .sort();
126	};
127	
128	const buildPlan = async (
129	  sourceDb: Db,
130	  targetDb: Db
131	): Promise<CollectionPlan[]> => {
132	  const names = await listCollectionNames(sourceDb);
133	  const plan: CollectionPlan[] = [];
134	
135	  for (const name of names) {
136	    const sourceCollection = sourceDb.collection(name);
137	    const targetCollection = targetDb.collection(name);
138	    // biome-ignore lint/performance/noAwaitInLoops: one-time migration script; a handful of collections, sequential keeps the plan output ordered and any error attributable
139	    const sourceCount = await sourceCollection.countDocuments();
140	    const targetCountBefore = await targetCollection.countDocuments();
141	    const rawIndexes = await sourceCollection.indexes();
142	    const indexSpecs = rawIndexes
143	      .filter((index) => index.name !== ID_INDEX_NAME)
144	      .map(toIndexSpec);
145	    plan.push({ indexSpecs, name, sourceCount, targetCountBefore });
146	  }
147	
148	  return plan;
149	};
150	
151	const printPlan = (plan: CollectionPlan[], source: string, target: string) => {
152	  console.log(`Source database: "${source}"`);
153	  console.log(`Target database: "${target}"`);
154	  console.table(
155	    plan.map((entry) => ({
156	      collection: entry.name,
157	      "indexes to create": entry.indexSpecs.length,
158	      "source docs": entry.sourceCount,
159	      "target docs (before)": entry.targetCountBefore,
160	    }))
161	  );
162	};
163	
164	const asWriteErrorArray = (writeErrors: MongoBulkWriteError["writeErrors"]) =>
165	  Array.isArray(writeErrors) ? writeErrors : [writeErrors];
166	
167	const insertBatch = async (
168	  target: Collection<Document>,
169	  docs: Document[]
170	): Promise<{ inserted: number; skipped: number }> => {
171	  if (docs.length === 0) {
172	    return { inserted: 0, skipped: 0 };
173	  }
174	
175	  try {
176	    const result = await target.insertMany(docs, { ordered: false });
177	    return { inserted: result.insertedCount, skipped: 0 };
178	  } catch (error) {
179	    if (error instanceof MongoBulkWriteError) {
180	      const writeErrors = asWriteErrorArray(error.writeErrors);
181	      const unexpected = writeErrors.filter(
182	        (writeError) => writeError.code !== DUPLICATE_KEY_ERROR_CODE
183	      );
184	      if (unexpected.length > 0) {
185	        throw error;
186	      }
187	      return {
188	        inserted: error.insertedCount,
189	        skipped: writeErrors.length,
190	      };
191	    }
192	    throw error;
193	  }
194	};
195	
196	const copyCollectionDocuments = async (
197	  sourceCollection: Collection<Document>,
198	  targetCollection: Collection<Document>
199	): Promise<{ inserted: number; skipped: number }> => {
200	  let inserted = 0;
201	  let skipped = 0;
202	  let batch: Document[] = [];
203	
204	  const flush = async () => {
205	    const result = await insertBatch(targetCollection, batch);
206	    inserted += result.inserted;
207	    skipped += result.skipped;
208	    batch = [];
209	  };
210	
211	  const cursor = sourceCollection.find({}, { batchSize: INSERT_BATCH_SIZE });
212	  for await (const doc of cursor) {
213	    batch.push(doc);
214	    if (batch.length >= INSERT_BATCH_SIZE) {
215	      // Sequential by design: batches must land in order so a mid-copy
216	      // failure leaves a resumable prefix, not gaps.
217	      await flush();
218	    }
219	  }
220	  await flush();
221	
222	  return { inserted, skipped };
223	};
224	
225	const createMissingIndexes = async (
226	  target: Collection<Document>,
227	  specs: IndexDescription[]
228	): Promise<number> => {
229	  if (specs.length === 0) {
230	    return 0;
231	  }
232	  // createIndexes is itself idempotent: recreating an index identical to one
233	  // that already exists is a no-op, not an error.
234	  const created = await target.createIndexes(specs);
235	  return created.length;
236	};
237	
238	const applyPlan = async (
239	  sourceDb: Db,
240	  targetDb: Db,
241	  plan: CollectionPlan[]
242	): Promise<void> => {
243	  for (const entry of plan) {
244	    const sourceCollection = sourceDb.collection(entry.name);
245	    const targetCollection = targetDb.collection(entry.name);
246	
247	    // biome-ignore lint/performance/noAwaitInLoops: sequential one-time migration; collections are copied one at a time so progress output stays ordered and any error is attributable to a single collection
248	    const indexesCreated = await createMissingIndexes(
249	      targetCollection,
250	      entry.indexSpecs
251	    );
252	    const { inserted, skipped } = await copyCollectionDocuments(
253	      sourceCollection,
254	      targetCollection
255	    );
256	    console.log(
257	      `"${entry.name}": ${inserted} inserted, ${skipped} already present, ${indexesCreated} index(es) ensured.`
258	    );
259	  }
260	};
261	
262	interface VerifyRow {
263	  readonly match: boolean;
264	  readonly name: string;
265	  readonly sourceCount: number;
266	  readonly targetCount: number;
267	}
268	
269	const verify = async (
270	  sourceDb: Db,
271	  targetDb: Db,
272	  names: readonly string[]
273	): Promise<VerifyRow[]> => {
274	  const rows: VerifyRow[] = [];
275	  for (const name of names) {
276	    // biome-ignore lint/performance/noAwaitInLoops: sequential verification pass over a handful of collections
277	    const sourceCount = await sourceDb.collection(name).countDocuments();
278	    const targetCount = await targetDb.collection(name).countDocuments();
279	    rows.push({
280	      match: sourceCount === targetCount,
281	      name,
282	      sourceCount,
283	      targetCount,
284	    });
285	  }
286	  return rows;
287	};
288	
289	const run = async () => {
290	  const uri = process.env.MONGODB_URI;
291	  if (!uri) {
292	    console.error("MONGODB_URI is required");
293	    process.exit(1);
294	  }
295	
296	  const { apply, source, target } = parseArgs(process.argv.slice(2));
297	
298	  if (source === target) {
299	    console.error(
300	      `Source and target database names are both "${source}" — refusing to run. This migration copies FROM the source INTO the target; running it against a single database would be a self-referential no-op at best and a corruption risk at worst.`
301	    );
302	    process.exit(1);
303	  }
304	
305	  const client = new MongoClient(uri);
306	
307	  try {
308	    await client.connect();
309	    const sourceDb = client.db(source);
