// Polls Atlas search index readiness. autoEmbed builds vectors asynchronously
// after seeding, so Substrate A must not start until facts_vector is QUERYABLE
// and its embedded document count matches the seeded fact count.
// Never prints the connection string.
import { MongoClient } from "mongodb";

const uri = process.env.KNOWLEDGE_MONGODB_URI;
if (!uri) {
  throw new Error("KNOWLEDGE_MONGODB_URI is required");
}

const client = new MongoClient(uri, { maxPoolSize: 2 });
await client.connect();
try {
  const db = client.db(process.env.KNOWLEDGE_MONGODB_DB ?? "knowledge");
  const facts = db.collection("facts");
  const total = await facts.countDocuments();
  process.stdout.write(`facts in collection: ${total}\n\n`);

  const indexes = await facts.listSearchIndexes().toArray();
  for (const index of indexes) {
    process.stdout.write(
      `${index.name}: status=${index.status} queryable=${index.queryable}\n`
    );
  }
} finally {
  await client.close();
}

