// First live exercise of the hybrid read path. $rankFusion over $search +
// $vectorSearch needs mongot, which the local test container lacks, so this
// composition has only ever been verified by unit tests until now.
//
// Checks, in order of what fails first if something is wrong:
//   1. the lexical arm alone returns something
//   2. the vector arm alone returns something (i.e. autoEmbed actually embedded)
//   3. the fused pipeline returns something
//   4. tenant isolation holds
// Never prints the connection string.
import { getCollections, retrieveFacts } from "@repo/knowledge";
import { MongoClient } from "mongodb";

const uri = process.env.KNOWLEDGE_MONGODB_URI;
if (!uri) {
  throw new Error("KNOWLEDGE_MONGODB_URI is required");
}

const ALPHA = "eval-tenant-alpha";
const BETA = "eval-tenant-beta";

const client = new MongoClient(uri, { ignoreUndefined: true, maxPoolSize: 2 });
await client.connect();

try {
  const db = client.db(process.env.KNOWLEDGE_MONGODB_DB ?? "knowledge");
  const { facts } = getCollections(db);

  // 1. lexical arm
  const lexical = await facts
    .aggregate([
      {
        $search: {
          compound: {
            filter: [{ equals: { path: "tenantId", value: ALPHA } }],
            must: [
              {
                text: {
                  path: ["text", { multi: "german", value: "text" }],
                  query: "Kowalski Termine",
                },
              },
            ],
          },
          index: "facts_search",
        },
      },
      { $limit: 3 },
      { $project: { text: 1 } },
    ])
    .toArray();
  process.stdout.write(`1. lexical arm: ${lexical.length} hits\n`);
  for (const hit of lexical) {
    process.stdout.write(`   ${String(hit.text).slice(0, 80)}\n`);
  }

  // 2. vector arm — proves autoEmbed embedded the seeded facts
  const vector = await facts
    .aggregate([
      {
        $vectorSearch: {
          filter: { tenantId: ALPHA },
          index: "facts_vector",
          limit: 3,
          numCandidates: 100,
          path: "text",
          query: { text: "Wann trifft sich Martin Kowalski am liebsten?" },
        },
      },
      { $project: { text: 1 } },
    ])
    .toArray();
  process.stdout.write(`\n2. vector arm: ${vector.length} hits\n`);
  for (const hit of vector) {
    process.stdout.write(`   ${String(hit.text).slice(0, 80)}\n`);
  }

  // 3. the fused read path as the agent calls it
  const fused = await retrieveFacts(db, {
    limit: 5,
    query: "Wann trifft sich Martin Kowalski am liebsten?",
    tenantId: ALPHA,
  });
  process.stdout.write(`\n3. $rankFusion: ${fused.length} hits\n`);
  for (const { fact } of fused) {
    process.stdout.write(
      `   ${fact._id.toHexString()} ${fact.text.slice(0, 70)}\n`
    );
  }

  // 4. tenant isolation
  const betaLeak = fused.filter(({ fact }) => fact.tenantId !== ALPHA);
  process.stdout.write(
    `\n4. tenant isolation: ${betaLeak.length === 0 ? "OK — no foreign tenant in results" : `LEAK — ${betaLeak.length}`}\n`
  );

  const betaSide = await retrieveFacts(db, {
    limit: 5,
    query: "Martin Kowalski Rolle",
    tenantId: BETA,
  });
  process.stdout.write(
    `   beta query returns ${betaSide.length} hits, all beta: ${betaSide.every(({ fact }) => fact.tenantId === BETA)}\n`
  );
} finally {
  await client.close();
}

